#include <stdio.h>
#include <stdlib.h>
typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;
BiTree Create(void)
{
    BiTree T;
    char ch = getchar();
    if (ch == '#')
        return NULL;
    T = (BiTNode *)malloc(sizeof(BiTNode));
    T->data = ch;
    T->lchild = Create();
    T->rchild = Create();
    return T;
}
/* k 为 0、1、2 时分别做先序、中序、后序遍历 */
void Order(BiTree T, int k)
{
    if (T == NULL)
        return;
    if (k == 0) putchar(T->data);
    Order(T->lchild, k);
    if (k == 1) putchar(T->data);
    Order(T->rchild, k);
    if (k == 2) putchar(T->data);
}

int main(void)
{
    BiTree T = Create();
    int k;
    for (k = 0; k < 3; k++) {
        Order(T, k);
        putchar('\n');
    }
    return 0;
}

