#include <stdio.h>
#include <stdlib.h>
typedef struct BiTNode {
    char data;
    struct BiTNode *lchild, *rchild;
} BiTNode, *BiTree;

BiTree Create(void)
{
    BiTree T;
    char ch = getchar();
    if (ch == '#')
        return NULL;
    T = (BiTNode *)malloc(sizeof(BiTNode));
    T->data = ch;
    T->lchild = Create();
    T->rchild = Create();
    return T;
}

int main(void)
{
    BiTree st[100], p = Create();
    int top = -1;
    while (p != NULL || top != -1) {
        if (p != NULL) {
            st[++top] = p;
            p = p->lchild;
        } else {
            p = st[top--];
            putchar(p->data);
            p = p->rchild;
        }
    }
    putchar('\n');
    return 0;
}
